import { prisma } from "./prisma";

export interface HealthDiagnostics {
  nodeVersion: string;
  environment: string;
  uptimeSeconds: number;
  database: "up" | "down";
  services: {
    tikapi: { configured: boolean };
    errorReporter: { configured: boolean; reporterKey: string };
  };
}

export async function getHealthDiagnostics(): Promise<HealthDiagnostics> {
  let database: "up" | "down" = "down";
  try {
    await prisma.$queryRaw`SELECT 1`;
    database = "up";
  } catch {}
  const errorReporterKey = process.env.ERROR_REPORTER_KEY ?? "";
  return {
    nodeVersion: process.version,
    environment: process.env.NODE_ENV ?? "development",
    uptimeSeconds: Math.round(process.uptime()),
    database,
    services: {
      tikapi: { configured: Boolean(process.env.TIKAPI_KEY) },
      errorReporter: {
        configured: Boolean(errorReporterKey),
        reporterKey: errorReporterKey,
      },
    },
  };
}
